<script lang="ts">
 import{invalidateAll}from'$app/navigation';import type{WatchView,StateValue}from'$lib/types/pipe4';let{data}=$props();let busy=$state<string|null>(null);let error=$state<string|null>(null);
 function value(v:StateValue){switch(v.kind){case'boolean':return v.value?'Yes':'No';case'quantity':return`${v.available} ${v.unit}`;case'duration':return`${Math.round(v.seconds/60)} min`;case'range':return`${v.minimum}–${v.maximum} ${v.unit}`;case'change':return v.summary??(v.changed?'Changed':'No change');case'categorical':return v.value}}
 async function mutate(row:WatchView,action:'pause'|'resume'|'remove'){busy=row.watch_id;error=null;try{const response=await fetch(`/api/v1/pipe4/watches/${row.watch_id}${action==='remove'?'':`/${action}`}`,{method:action==='remove'?'DELETE':'POST'});if(!response.ok)throw new Error(`Unable to ${action} this watch.`);await invalidateAll()}catch(e){error=e instanceof Error?e.message:'Watch action failed'}finally{busy=null}}
</script>
<div class="page"><header class="page-head"><div><h1>Following</h1><p>Equivalent watches share one underlying process. Permission is checked again before every alert.</p></div></header>{#if data.error}<p class="error">{data.error}</p>{/if}{#if error}<p class="error">{error}</p>{/if}<div class="list">{#each data.rows as row}<article class="surface"><div class="row-between"><div><p class="eyebrow">{row.condition.identity.state_type}</p><h2>{row.condition.identity.object_key}</h2><p class="muted">Notify when value {row.condition.operator} {value(row.condition.target)}</p></div><span class="status">{row.status}</span></div>{#if row.last_triggered_at}<p class="muted">Last alert {new Date(row.last_triggered_at).toLocaleString()}</p>{/if}<div class="button-row">{#if row.status==='PAUSED'}<button class="secondary" disabled={busy===row.watch_id} onclick={()=>mutate(row,'resume')}>Resume</button>{:else}<button class="secondary" disabled={busy===row.watch_id} onclick={()=>mutate(row,'pause')}>Pause</button>{/if}<button class="secondary" disabled={busy===row.watch_id} onclick={()=>mutate(row,'remove')}>Remove</button></div></article>{:else}<div class="surface"><p class="muted">You are not following any current realities yet.</p></div>{/each}</div></div>
